import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test user registration API rejects duplicate emails (/auth/user/join).
 *
 * 1. Register a user with a unique, random email address to ensure it exists
 *    (prerequisite).
 * 2. Attempt registration with the same email but a different password and session
 *    metadata.
 * 3. The duplicate registration should fail; assert error is thrown to confirm
 *    uniqueness enforcement.
 */
export async function test_api_user_registration_duplicate_email(
  connection: api.IConnection,
) {
  const email = typia.random<
    string & tags.MinLength<5> & tags.MaxLength<255> & tags.Format<"email">
  >();
  const firstJoinBody = {
    email,
    password: RandomGenerator.alphaNumeric(12),
    href: "https://www.todolist-app.com/signup",
    referrer: "https://www.todolist-app.com/",
  } satisfies ITodoListUser.IJoin;

  const firstJoin = await api.functional.auth.user.join(connection, {
    body: firstJoinBody,
  });
  typia.assert(firstJoin);

  const secondJoinBody = {
    email,
    password: RandomGenerator.alphaNumeric(14),
    href: "https://www.todolist-app.com/dup",
    referrer: "https://www.todolist-app.com/from-test",
  } satisfies ITodoListUser.IJoin;

  await TestValidator.error(
    "should reject registration with duplicate email",
    async () => {
      await api.functional.auth.user.join(connection, { body: secondJoinBody });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate that a user with an unverified email cannot successfully log in and
 * receives a generic error response.
 *
 * 1. Register a new user (without verifying the email) and capture the
 *    email/password used.
 * 2. Attempt to log in with those credentials.
 * 3. Assert that login attempt fails with a generic error (no information leak
 *    about whether due to email, password, or verification status).
 */
export async function test_api_user_login_unverified_email(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const joinBody = {
    email: typia.random<
      string & tags.MinLength<5> & tags.MaxLength<255> & tags.Format<"email">
    >(),
    password: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>(),
    href: "https://e2e-test.tld/register",
    referrer: "https://e2e-test.tld/landing",
  } satisfies ITodoListUser.IJoin;
  const newUser: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: joinBody });
  typia.assert(newUser);
  TestValidator.equals(
    "registered email matches input",
    newUser.email,
    joinBody.email,
  );
  TestValidator.predicate(
    "user is not verified immediately after registration",
    newUser.is_verified === false,
  );

  // 2. Attempt login with registered credentials (should fail)
  const loginBody = {
    email: joinBody.email,
    password: joinBody.password as string & tags.Format<"password">,
    href: "https://e2e-test.tld/login",
    referrer: "https://e2e-test.tld/register",
  } satisfies ITodoListUser.ILogin;
  await TestValidator.error(
    "login with unverified email should fail generically",
    async () => {
      await api.functional.auth.user.login(connection, { body: loginBody });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";

/**
 * Verify detailed audit/session retrieval with valid/invalid user-session
 * linkage.
 *
 * 1. Prepare a mock session record (random UUIDs for userId and sessionId)
 * 2. Call api.functional.todoList.users.sessions.at with these parameters
 * 3. Assert full ITodoListUserSession shape and all fields using typia.assert()
 * 4. Validate returned object's todo_list_user_id === userId; id === sessionId
 * 5. Validate ip, href, referrer, created_at are all non-empty (string, date-time
 *    as appropriate)
 * 6. (Edge case) Call with correct sessionId but mismatched userId; confirm error
 *    or forbidden
 */
export async function test_api_user_session_detailed_audit_retrieval(
  connection: api.IConnection,
) {
  // 1. Generate random but valid userId and sessionId
  const userId = typia.random<string & tags.Format<"uuid">>();
  const sessionId = typia.random<string & tags.Format<"uuid">>();

  // 2. Success case: retrieve session by correct linkage
  const session: ITodoListUserSession =
    await api.functional.todoList.users.sessions.at(connection, {
      userId,
      sessionId,
    });
  typia.assert(session);
  TestValidator.equals(
    "session.user linkage correct",
    session.todo_list_user_id,
    userId,
  );
  TestValidator.equals("session.id matches sessionId", session.id, sessionId);
  TestValidator.predicate(
    "session IP provided",
    typeof session.ip === "string" && session.ip.length > 0,
  );
  TestValidator.predicate(
    "href provided",
    typeof session.href === "string" && session.href.length > 0,
  );
  TestValidator.predicate(
    "referrer always string",
    typeof session.referrer === "string",
  );
  TestValidator.predicate(
    "created_at date-time string",
    typeof session.created_at === "string" && session.created_at.length > 0,
  );

  // 3. Edge case: attempt lookup with correct sessionId but wrong userId
  const wrongUserId = typia.random<string & tags.Format<"uuid">>();
  if (wrongUserId !== userId) {
    await TestValidator.error(
      "denies access/session not belonging to user",
      async () => {
