import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { IPageITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoListUserTodos(props: {
  user: UserPayload;
  body: ITodoListTodo.IRequest;
}): Promise<IPageITodoListTodo.ISummary> {
  const {
    keyword,
    status,
    created_from,
    created_to,
    page = 1,
    limit = 20,
    order = "created_at:desc",
  } = props.body || {};

  const take = Math.max(Math.min(limit, 100), 1);
  const skip = (Math.max(page, 1) - 1) * take;

  // Build where condition, handling all optional filters
  const where: Record<string, unknown> = {
    user_id: props.user.id,
    ...(status && { status }),
    ...(keyword && {
      OR: [
        { title: { contains: keyword } },
        { description: { contains: keyword } },
      ],
    }),
    ...(created_from && created_to
      ? { created_at: { gte: created_from, lte: created_to } }
      : created_from
        ? { created_at: { gte: created_from } }
        : created_to
          ? { created_at: { lte: created_to } }
          : {}),
  };

  const parts = order.split(":");
  const orderBy = {
    [parts[0]]: parts[1] === "asc" ? "asc" : "desc",
  } as { [key: string]: Prisma.SortOrder };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_list_todos.findMany({
      where,
      skip,
      take,
      orderBy,
    }),
    MyGlobal.prisma.todo_list_todos.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: take,
      records: total,
      pages: Math.ceil(total / take),
    },
    data: rows.map((row) => ({
      id: row.id,
      title: row.title,
      status: typia.assert<"incomplete" | "complete">(row.status),
      completed_at: row.completed_at ? toISOStringSafe(row.completed_at) : null,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserRefresh(props: {
  body: ITodoListUser.IRefresh;
}): Promise<ITodoListUser.IAuthorized> {
  let decoded;
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    );
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (!decoded || typeof decoded === "string" || decoded.type !== "user") {
    throw new HttpException("Invalid token type", 403);
  }
  const session = await MyGlobal.prisma.todo_list_user_sessions.findFirst({
    where: { id: decoded.session_id, todo_list_user_id: decoded.id },
    include: { user: true },
  });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  const user = session.user;
  if (
    user.deleted_at !== null ||
    user.locked === true ||
    user.is_verified === false
  ) {
    throw new HttpException("Account not active or verified", 403);
  }
  if (
    session.expired_at &&
    Date.parse(toISOStringSafe(session.expired_at)) < Date.now()
  ) {
    throw new HttpException("Session has expired", 401);
  }
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  const token = {
    access: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };
  await MyGlobal.prisma.todo_list_user_sessions.update({
    where: { id: session.id },
    data: { expired_at: refreshExpires },
  });
  return {
    id: user.id,
    email: user.email,
    is_verified: user.is_verified,
    locked: user.locked,
    locked_at: user.locked_at ? toISOStringSafe(user.locked_at) : undefined,
    email_verification_token: user.email_verification_token ?? undefined,
    email_verification_sent_at: user.email_verification_sent_at
      ? toISOStringSafe(user.email_verification_sent_at)
      : undefined,
    reset_password_token: user.reset_password_token ?? undefined,
    reset_password_sent_at: user.reset_password_sent_at
      ? toISOStringSafe(user.reset_password_sent_at)
      : undefined,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at: user.deleted_at ? toISOStringSafe(user.deleted_at) : undefined,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoListUserTodos(props: {
  user: UserPayload;
  body: ITodoListTodo.ICreate;
}): Promise<ITodoListTodo> {
  // 1. Generate new UUID for the todo item
  const todoId = v4();
  const now = toISOStringSafe(new Date());

  // 2. Check for per-user title uniqueness (case-insensitive)
  const existing = await MyGlobal.prisma.todo_list_todos.findFirst({
    where: {
      user_id: props.user.id,
      title: props.body.title,
    },
  });

  if (existing) {
    throw new HttpException(
      "A todo with this title already exists for this user.",
      409,
    );
  }

  // 3. Insert new todo row
  const created = await MyGlobal.prisma.todo_list_todos.create({
    data: {
      id: todoId,
      user_id: props.user.id,
      title: props.body.title,
      description: props.body.description ?? null,
      status: "incomplete",
      completed_at: null,
      created_at: now,
      updated_at: now,
    },
  });

  // 4. Fetch user summary
  const userSummary = await MyGlobal.prisma.todo_list_users.findUnique({
    where: { id: props.user.id },
    select: { id: true, email: true },
  });

  if (!userSummary) {
    throw new HttpException("User not found for response embedding.", 500);
  }

  return {
    id: created.id,
    user: {
      id: userSummary.id,
      email: userSummary.email,
    },
    title: created.title,
    description: created.description ?? undefined,
    status: typia.assert<"incomplete" | "complete">(created.status),
    completed_at: created.completed_at
      ? toISOStringSafe(created.completed_at)
      : undefined,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoListUserTodosTodoId(props: {
  user: UserPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoListTodo.IUpdate;
}): Promise<ITodoListTodo> {
  const { user, todoId, body } = props;
  // Find todo owned by this user
  const existing = await MyGlobal.prisma.todo_list_todos.findUnique({
    where: {
      id: todoId,
      user_id: user.id,
    },
    include: { user: true },
  });
  if (!existing) {
    throw new HttpException("Todo not found or not owned by user", 404);
  }
  // Unique title enforcement: only check if title is provided and different
  if (body.title !== undefined && body.title !== existing.title) {
    const duplicate = await MyGlobal.prisma.todo_list_todos.findFirst({
      where: {
        user_id: user.id,
        title: body.title,
        NOT: { id: todoId },
      },
    });
    if (duplicate) {
      throw new HttpException("Title must be unique for this user", 409);
    }
  }
  // Handle completed_at business logic
  let completedAt: Date | null = existing.completed_at;
  if (body.status !== undefined && body.status !== existing.status) {
    if (body.status === "complete") {
      completedAt = new Date();
    } else {
      completedAt = null;
    }
  }
  const now = new Date();
  const updated = await MyGlobal.prisma.todo_list_todos.update({
    where: {
      id: todoId,
      user_id: user.id,
    },
    data: {
      ...(body.title !== undefined && { title: body.title }),
      ...(body.description !== undefined && { description: body.description }),
      ...(body.status !== undefined && { status: body.status }),
      completed_at: completedAt,
      updated_at: now,
    },
    include: { user: true },
  });
  return {
    id: updated.id,
    user: {
      id: updated.user.id,
      email: updated.user.email,
    },
    title: updated.title,
    description: updated.description === null ? null : updated.description,
    status: typia.assert<"incomplete" | "complete">(updated.status),
    completed_at: updated.completed_at
      ? toISOStringSafe(updated.completed_at)
      : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { UserPayload } from "../decorators/payload/UserPayload";

export async function deleteTodoListUserUsersUserId(props: {
  user: UserPayload;
  userId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Only allow users to delete their own accounts
  if (props.user.id !== props.userId) {
    throw new HttpException(
      "You are not permitted to delete another user's account.",
      403,
    );
  }

  // Ensure the user exists and is not already deleted
  const existing = await MyGlobal.prisma.todo_list_users.findUnique({
    where: {
      id: props.userId,
      deleted_at: null,
    },
  });
  if (!existing) {
    throw new HttpException("User not found or already deleted.", 404);
  }

  // Hard delete the user; schema-level cascade cleans up related records
  await MyGlobal.prisma.todo_list_users.delete({
    where: {
      id: props.userId,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IPageITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoListUserUsers(props: {
  user: UserPayload;
  body: ITodoListUser.IRequest;
}): Promise<IPageITodoListUser.ISummary> {
  const {
    page,
    limit,
    email,
    is_verified,
    locked,
    from_date,
    to_date,
    sort_by,
    sort_order,
  } = props.body;
  const skip = (page - 1) * limit;

  // Build Prisma where condition based on optional filters
  const where = {
    deleted_at: null,
    ...(typeof email === "string" ? { email: email } : {}),
    ...(typeof is_verified === "boolean" ? { is_verified: is_verified } : {}),
    ...(typeof locked === "boolean" ? { locked: locked } : {}),
    ...(from_date || to_date
      ? {
          created_at: {
            ...(from_date ? { gte: from_date } : {}),
            ...(to_date ? { lte: to_date } : {}),
          },
        }
      : {}),
  };

  // Restrict sort field and order to schema allowed values
  const sortableColumns = ["created_at", "email"] as const;
  const usedSortBy = sortableColumns.includes(
    sort_by as (typeof sortableColumns)[number],
  )
    ? sort_by
    : "created_at";
  const usedSortOrder =
    sort_order === "asc" || sort_order === "desc" ? sort_order : "desc";
  // Prisma expects the sort key to be a plain string, not possibly undefined
  const orderBy: Record<string, "asc" | "desc"> = {
    [usedSortBy!]: usedSortOrder,
  };

  // Query users and count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_list_users.findMany({
      where,
      skip,
      take: limit,
      orderBy,
      select: {
        id: true,
        email: true,
      },
    }),
    MyGlobal.prisma.todo_list_users.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((user) => ({
      id: user.id,
      email: user.email,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";
import { IPageITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUserSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchTodoListUsersUserIdSessions(props: {
  userId: string & tags.Format<"uuid">;
  body: ITodoListUserSession.IRequest;
}): Promise<IPageITodoListUserSession.ISummary> {
  const {
    created_at_gte,
    created_at_lte,
    expired_only,
    ip_contains,
    user_agent_contains,
    page,
    limit,
    order_by,
    order_direction,
  } = props.body;

  // Pagination defaults
  const pageIndex = page ?? 1;
  const pageLimit = limit ?? 100;
  const skip = (pageIndex - 1) * pageLimit;

  // Build created_at filter
  let createdAtFilter: { gte?: string; lte?: string } = {};
  if (created_at_gte !== undefined) {
    createdAtFilter.gte = created_at_gte;
  }
  if (created_at_lte !== undefined) {
    createdAtFilter.lte = created_at_lte;
  }

  // Build where conditions
  const where: Record<string, unknown> = {
    todo_list_user_id: props.userId,
    ...(createdAtFilter.gte !== undefined || createdAtFilter.lte !== undefined
      ? {
          created_at: { ...createdAtFilter },
        }
      : {}),
    ...(typeof expired_only === "boolean"
      ? expired_only
        ? { expired_at: { not: null } }
        : { expired_at: null }
      : {}),
    ...(ip_contains ? { ip: { contains: ip_contains } } : {}),
    ...(user_agent_contains
      ? { user_agent: { contains: user_agent_contains } }
      : {}),
  };

  // Determine orderBy
  const sortField: "created_at" | "expired_at" = order_by ?? "created_at";
  const sortDirection: "asc" | "desc" = order_direction ?? "desc";
  const orderBy = { [sortField]: sortDirection };

  // Query DB
  const [sessions, total] = await Promise.all([
    MyGlobal.prisma.todo_list_user_sessions.findMany({
      where,
      orderBy,
      skip,
      take: pageLimit,
    }),
    MyGlobal.prisma.todo_list_user_sessions.count({ where }),
  ]);

  const data = sessions.map((session) => ({
    id: session.id,
    created_at: toISOStringSafe(session.created_at),
    expired_at:
      session.expired_at !== null && session.expired_at !== undefined
        ? toISOStringSafe(session.expired_at)
        : undefined,
  }));

  return {
    pagination: {
      current: pageIndex,
      limit: pageLimit,
      records: total,
      pages: Math.ceil(total / pageLimit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoListUser.IJoin;
}): Promise<ITodoListUser.IAuthorized> {
  // Step 1: Duplicate email check (exclude soft-deleted)
  const existing = await MyGlobal.prisma.todo_list_users.findFirst({
    where: { email: props.body.email, deleted_at: null },
  });
  if (existing) {
    throw new HttpException("Email already registered.", 409);
  }

  // Step 2: Prepare all time values and IDs
  const now = toISOStringSafe(new Date());
  const userId = v4();
  const sessionId = v4();
  const verificationToken = v4(); // using uuid strategy for OTK
  const emailVerificationSentAt = now;

  // Step 3: Password hashing
  const passwordHash = await PasswordUtil.hash(props.body.password);

  // Step 4: User record insert
  const user = await MyGlobal.prisma.todo_list_users.create({
    data: {
      id: userId,
      email: props.body.email,
      password_hash: passwordHash,
      is_verified: false,
      email_verification_token: verificationToken,
      email_verification_sent_at: emailVerificationSentAt,
      reset_password_token: null,
      reset_password_sent_at: null,
      locked: false,
      locked_at: null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // Step 5: Session insert
  const sessionData: any = {
    id: sessionId,
    todo_list_user_id: userId,
    href: props.body.href,
    referrer: props.body.referrer,
    created_at: now,
    expired_at: null,
  };
  if (props.body.ip !== null && props.body.ip !== undefined) {
    sessionData.ip = props.body.ip satisfies string as string;
  }
  await MyGlobal.prisma.todo_list_user_sessions.create({
    data: sessionData,
  });

  // Step 6: JWT token creation (all issued now)
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: userId,
        session_id: sessionId,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: userId,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Step 7: Return - map output strictly to IAuthorized (respect null/undefined)
  return {
    id: user.id,
    email: user.email,
    is_verified: user.is_verified,
    locked: user.locked,
    locked_at: user.locked_at ? toISOStringSafe(user.locked_at) : null,
    email_verification_token: user.email_verification_token ?? null,
    email_verification_sent_at: user.email_verification_sent_at
      ? toISOStringSafe(user.email_verification_sent_at)
      : null,
    reset_password_token: user.reset_password_token ?? null,
    reset_password_sent_at: user.reset_password_sent_at
      ? toISOStringSafe(user.reset_password_sent_at)
      : null,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at: user.deleted_at ? toISOStringSafe(user.deleted_at) : null,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
